

import typing

from ..core.client_wrapper import AsyncClientWrapper, SyncClientWrapper
from ..core.request_options import RequestOptions
from ..types.bot_create_response import BotCreateResponse
from ..types.bot_manager_response import BotManagerResponse
from ..types.cursor import Cursor
from ..types.managed_bot_response import ManagedBotResponse
from ..types.uuid_ import Uuid
from .raw_client import AsyncRawBotsClient, RawBotsClient
from .types.check_managed_bot_username_response import CheckManagedBotUsernameResponse
from .types.list_bots_response import ListBotsResponse


OMIT = typing.cast(typing.Any, ...)


class BotsClient:
    def __init__(self, *, client_wrapper: SyncClientWrapper):
        self._raw_client = RawBotsClient(client_wrapper=client_wrapper)

    @property
    def with_raw_response(self) -> RawBotsClient:
        """
        Retrieves a raw implementation of this client that returns raw responses.

        Returns
        -------
        RawBotsClient
        """
        return self._raw_client

    def list_bots(
        self,
        *,
        cursor: typing.Optional[Cursor] = None,
        limit: typing.Optional[int] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> ListBotsResponse:
        """
        Parameters
        ----------
        cursor : typing.Optional[Cursor]

        limit : typing.Optional[int]

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        ListBotsResponse
            The request has succeeded.

        Examples
        --------
        from fern import FernApi

        client = FernApi(
            api_key="YOUR_API_KEY",
            token="YOUR_TOKEN",
        )
        client.bots.list_bots()
        """
        _response = self._raw_client.list_bots(cursor=cursor, limit=limit, request_options=request_options)
        return _response.data

    def create_bots(
        self,
        *,
        idempotency_key: Uuid,
        tokens: typing.Sequence[str],
        request_options: typing.Optional[RequestOptions] = None,
    ) -> BotCreateResponse:
        """
        Parameters
        ----------
        idempotency_key : Uuid
            Stable UUID generated by the caller for safe request retries.

        tokens : typing.Sequence[str]
            Telegram bot tokens. Tokens are never returned by the API.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        BotCreateResponse
            The request has succeeded.

        Examples
        --------
        from fern import FernApi

        client = FernApi(
            api_key="YOUR_API_KEY",
            token="YOUR_TOKEN",
        )
        client.bots.create_bots(
            idempotency_key="Idempotency-Key",
            tokens=["tokens"],
        )
        """
        _response = self._raw_client.create_bots(
            idempotency_key=idempotency_key, tokens=tokens, request_options=request_options
        )
        return _response.data

    def get_bot_manager(self, *, request_options: typing.Optional[RequestOptions] = None) -> BotManagerResponse:
        """
        Parameters
        ----------
        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        BotManagerResponse
            Manager configuration for the current account, without credentials.

        Examples
        --------
        from fern import FernApi

        client = FernApi(
            api_key="YOUR_API_KEY",
            token="YOUR_TOKEN",
        )
        client.bots.get_bot_manager()
        """
        _response = self._raw_client.get_bot_manager(request_options=request_options)
        return _response.data

    def select_bot_manager(
        self, *, idempotency_key: Uuid, bot_id: int, request_options: typing.Optional[RequestOptions] = None
    ) -> BotManagerResponse:
        """
        Parameters
        ----------
        idempotency_key : Uuid
            Stable UUID generated by the caller for safe request retries.

        bot_id : int

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        BotManagerResponse
            Ownership and Bot Management Mode verified.

        Examples
        --------
        from fern import FernApi

        client = FernApi(
            api_key="YOUR_API_KEY",
            token="YOUR_TOKEN",
        )
        client.bots.select_bot_manager(
            idempotency_key="Idempotency-Key",
            bot_id=1000000,
        )
        """
        _response = self._raw_client.select_bot_manager(
            idempotency_key=idempotency_key, bot_id=bot_id, request_options=request_options
        )
        return _response.data

    def clear_bot_manager(self, *, request_options: typing.Optional[RequestOptions] = None) -> BotManagerResponse:
        """
        Parameters
        ----------
        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        BotManagerResponse
            Manager selection removed; Telegram bots remain intact.

        Examples
        --------
        from fern import FernApi

        client = FernApi(
            api_key="YOUR_API_KEY",
            token="YOUR_TOKEN",
        )
        client.bots.clear_bot_manager()
        """
        _response = self._raw_client.clear_bot_manager(request_options=request_options)
        return _response.data

    def check_managed_bot_username(
        self, *, username: str, request_options: typing.Optional[RequestOptions] = None
    ) -> CheckManagedBotUsernameResponse:
        """
        Parameters
        ----------
        username : str

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        CheckManagedBotUsernameResponse
            Available username. Creation checks availability again.

        Examples
        --------
        from fern import FernApi

        client = FernApi(
            api_key="YOUR_API_KEY",
            token="YOUR_TOKEN",
        )
        client.bots.check_managed_bot_username(
            username="username",
        )
        """
        _response = self._raw_client.check_managed_bot_username(username=username, request_options=request_options)
        return _response.data

    def create_managed_bot(
        self,
        *,
        idempotency_key: Uuid,
        name: str,
        username: str,
        channel_id: str,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> ManagedBotResponse:
        """
        Creates a user-owned bot, exports its token without rotation and registers it in the chosen private channel. Retrying the same username recovers setup instead of creating another bot.

        Parameters
        ----------
        idempotency_key : Uuid
            Stable UUID generated by the caller for safe request retries.

        name : str

        username : str

        channel_id : str

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        ManagedBotResponse
            Bot configured and ready for transfers in its channel.

        Examples
        --------
        from fern import FernApi

        client = FernApi(
            api_key="YOUR_API_KEY",
            token="YOUR_TOKEN",
        )
        client.bots.create_managed_bot(
            idempotency_key="Idempotency-Key",
            name="name",
            username="username",
            channel_id="channelId",
        )
        """
        _response = self._raw_client.create_managed_bot(
            idempotency_key=idempotency_key,
            name=name,
            username=username,
            channel_id=channel_id,
            request_options=request_options,
        )
        return _response.data

    def delete_bot(self, bot_id: int, *, request_options: typing.Optional[RequestOptions] = None) -> None:
        """
        Parameters
        ----------
        bot_id : int

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        None

        Examples
        --------
        from fern import FernApi

        client = FernApi(
            api_key="YOUR_API_KEY",
            token="YOUR_TOKEN",
        )
        client.bots.delete_bot(
            bot_id=1000000,
        )
        """
        _response = self._raw_client.delete_bot(bot_id, request_options=request_options)
        return _response.data


class AsyncBotsClient:
    def __init__(self, *, client_wrapper: AsyncClientWrapper):
        self._raw_client = AsyncRawBotsClient(client_wrapper=client_wrapper)

    @property
    def with_raw_response(self) -> AsyncRawBotsClient:
        """
        Retrieves a raw implementation of this client that returns raw responses.

        Returns
        -------
        AsyncRawBotsClient
        """
        return self._raw_client

    async def list_bots(
        self,
        *,
        cursor: typing.Optional[Cursor] = None,
        limit: typing.Optional[int] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> ListBotsResponse:
        """
        Parameters
        ----------
        cursor : typing.Optional[Cursor]

        limit : typing.Optional[int]

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        ListBotsResponse
            The request has succeeded.

        Examples
        --------
        import asyncio

        from fern import AsyncFernApi

        client = AsyncFernApi(
            api_key="YOUR_API_KEY",
            token="YOUR_TOKEN",
        )


        async def main() -> None:
            await client.bots.list_bots()


        asyncio.run(main())
        """
        _response = await self._raw_client.list_bots(cursor=cursor, limit=limit, request_options=request_options)
        return _response.data

